from math import comb


class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10 ** 9 + 7
        n = len(s)
        steps = [0] * (n + 1)
        for c in range(2, n + 1):
            steps[c] = steps[bin(c).count("1")] + 1
        good = [c for c in range(1, n + 1) if steps[c] <= k - 1]
        total = 0
        ones = 0
        for i, ch in enumerate(s):
            if ch == "1":
                remaining = n - i - 1
                for c in good:
                    need = c - ones
                    if 0 <= need <= remaining:
                        total += comb(remaining, need)
                ones += 1
        return total % mod

